layout(color) uniform half4 amzp_shadowColor;
uniform float amzp_shadowOpacity;
uniform float amzp_shadowBlur;
uniform float amzp_shiftX;
uniform float amzp_shiftY;
uniform float amzp_fgOpacity;
uniform float amzp_matteUse;
uniform float amzp_invertMatte;


        const float PI = 3.14159265;

        float getMatte(float4 col) {
            float mv;
            if (int(amzp_matteUse) == 1) {
                mv = dot(col.rgb, float3(0.299, 0.587, 0.114));
            } else {
                mv = col.a;
            }
            if (int(amzp_invertMatte) == 1) mv = 1.0 - mv;
            return clamp(mv, 0.0, 1.0);
        }


        float4 gaussianBlur(int tex, float2 uv, float2 texOffset, float kernelSize) {
            if (kernelSize <= 0.0) return amzTexture(tex, uv);

            float adjSigma = kernelSize / 2.14596602;

            float3 ig;
            ig.x = 1.0 / (sqrt(2.0 * PI) * adjSigma);
            ig.y = exp(-0.5 / (adjSigma * adjSigma));
            ig.z = ig.y * ig.y;

            float4 avgValue = amzTexture(tex, uv) * ig.x;
            float coeffSum = ig.x;

            for (float i = 1.0; i <= kernelSize; i += 2.0) {
                float offset0 = i;
                float offset1 = i + 1.0;

                ig.xy *= ig.yz;
                coeffSum += 2.0 * ig.x;
                float w0 = ig.x;

                ig.xy *= ig.yz;
                coeffSum += 2.0 * ig.x;
                float w1 = ig.x;

                float wL = w0 + w1;
                float oL = (offset0 * w0 + offset1 * w1) / wL;

                avgValue += amzTexture(tex, uv - oL * texOffset) * wL;
                avgValue += amzTexture(tex, uv + oL * texOffset) * wL;
            }

            return avgValue / coeffSum;
        }




        void pass0() {
            float2 uv = amzScreenNorm() - float2(amzp_shiftX, amzp_shiftY);
            float4 src = amzTexture(0, uv);
            float m = getMatte(src);
            amzOutput = float4(m, m, m, m);
        }




        void pass1() {
            float2 uv = amzScreenNorm();
            float kernelSize = amzp_shadowBlur / 2.0 * 1.14 / 4.0 / 3.0 * length(screen.zw);
            float2 texOffset = float2(1.0 / (screen.zw/2.0).x, 0.0);
            amzOutput = gaussianBlur(1, uv, texOffset, kernelSize);
        }




        void pass2() {
            float2 uv = amzScreenNorm();
            float kernelSize = amzp_shadowBlur / 2.0 * 1.14 / 4.0 / 3.0 * length(screen.zw);
            float2 texOffset = float2(0.0, 1.0 / (screen.zw/2.0).y);
            amzOutput = gaussianBlur(2, uv, texOffset, kernelSize);
        }




        void pass3() {
            float2 uv = amzScreenNorm();

            float blurredMatte = amzTexture(3, uv).r;
            float shadowMatte = clamp(blurredMatte * amzp_shadowOpacity, 0.0, 1.0);


            float4 shadow = float4(amzp_shadowColor.rgb * shadowMatte, shadowMatte);


            float4 fg = amzTexture(0, uv);
            float fgA = getMatte(fg) * amzp_fgOpacity;


            float3 rgb = shadow.rgb * (1.0 - fgA) + fg.rgb * fgA;
            float a   = shadow.a + fgA * (1.0 - shadow.a);

            amzOutput = float4(rgb, a);
        }

        void amzRender() {
            if (amzPass == 0) {
                pass0();
            } else if (amzPass == 1) {
                pass1();
            } else if (amzPass == 2) {
                pass2();
            } else {
                pass3();
            }
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

